export function originContractSources(): (OriginSelection & { name: string })[] {
  return documents.map(document => {
    const bytes = gunzipSync(Buffer.from(document.gzipBase64, "base64"), { maxOutputLength: Number(document.artifact.bytes) });
    assert.equal(String(bytes.length), document.artifact.bytes);
    assert.equal(originSha(bytes), document.artifact.sha256);
    return { name: document.name, artifact: { ...document.artifact }, kind: "fixed-contract-source", bytesHex: bytes.toString("hex") };
  });
}
